parameters.global_declarations:
#include <Wire.h>

#define MT6701_ADDR 0x06
#define MT6701_REG_ANGLE 0x03

static bool mt6701_initialized = false;
static double mt6701_prev_deg = 0.0;
static double mt6701_total_deg = 0.0;

parameters.step_code:
uint8_t highByte = 0;
uint8_t lowByte = 0;

// MT6701から2バイト(0x03, 0x04)読み出し
Wire.beginTransmission(MT6701_ADDR);
Wire.write(MT6701_REG_ANGLE);
Wire.endTransmission(false);

Wire.requestFrom(MT6701_ADDR, 2);
if (Wire.available() >= 2) {
    highByte = Wire.read();
    lowByte  = Wire.read();
}

// 14ビット合成・角度変換 [0 ~ 360 deg]
uint16_t raw_angle = ((uint16_t)highByte << 6) | (lowByte >> 2);
double current_deg = (double)raw_angle * 360.0 / 16384.0;

// 360度またぎ補正・相対角度の積算
if (!mt6701_initialized) {
    mt6701_prev_deg = current_deg;
    mt6701_total_deg = 0.0;
    mt6701_initialized = true;
} else {
    double diff = current_deg - mt6701_prev_deg;

    if (diff < -180.0) {
        diff += 360.0;
    } else if (diff > 180.0) {
        diff -= 360.0;
    }

    mt6701_total_deg += diff;
    mt6701_prev_deg = current_deg;
}

// 出力ポートへ代入
outputs[0] = (float)mt6701_total_deg;
